        node1_name = (await GriptapeNodes.ahandle_request(CreateNodeRequest(node_type='IntegerInput', specific_library_name='Griptape Nodes Library', node_name='Integer Input - Shared Steps', metadata={'position': {'x': 3800, 'y': 1868}, 'library_node_metadata': {'category': 'number', 'description': 'Create an integer (whole number) value with an input node.', 'display_name': 'Integer Input', 'tags': ['number', 'input', 'integer', 'create'], 'icon': None, 'color': None, 'group': 'create', 'deprecation': None, 'is_node_group': None, 'declarations': []}, 'library': 'Griptape Nodes Library', 'node_type': 'IntegerInput'}, resolution='resolved', initial_setup=True))).node_name
        node2_name = (await GriptapeNodes.ahandle_request(CreateNodeRequest(node_type='Flux2ImageGeneration', specific_library_name='Griptape Nodes Library', node_name='FLUX.2 Image Generation - Generate with API Model', metadata={'position': {'x': 4700, 'y': 1518}, 'library_node_metadata': {'category': 'image', 'description': 'Generate images using FLUX.2 models via Griptape model proxy', 'display_name': 'FLUX.2 Image Generation', 'tags': ['image', 'generation', 'ai', 'api', 'flux'], 'icon': 'Zap', 'color': None, 'group': 'create', 'deprecation': None, 'is_node_group': None, 'declarations': [{'type': 'model_usage', 'model_ids': ['gtc_flux_2_pro', 'gtc_flux_2_flex', 'gtc_flux_2_max', 'gtc_flux_2_klein_4b', 'gtc_flux_2_klein_9b']}]}, 'library': 'Griptape Nodes Library', 'node_type': 'Flux2ImageGeneration', 'size': {'width': 1200, 'height': 2000}}, initial_setup=True))).node_name
        node3_name = (await GriptapeNodes.ahandle_request(CreateNodeRequest(node_type='DisplayImage', specific_library_name='Griptape Nodes Library', node_name='Display Image - Online Result', metadata={'position': {'x': 6200, 'y': 1518}, 'library_node_metadata': {'category': 'image', 'description': 'Display an image', 'display_name': 'Display Image', 'tags': ['image', 'display'], 'icon': None, 'color': None, 'group': 'display', 'deprecation': None, 'is_node_group': None, 'declarations': []}, 'library': 'Griptape Nodes Library', 'node_type': 'DisplayImage', 'size': {'width': 1200, 'height': 940}}, initial_setup=True))).node_name
